using DomainModel.Context; using Microsoft.EntityFrameworkCore; namespace DataAccess.Repositories.Province; public class ProvinceRepository(ApplicationDbContext c):IProvinceRepository { public IQueryable<DomainModel.Models.Province> Query(bool tracking=false)=>tracking?c.Provinces:c.Provinces.AsNoTracking(); public Task<DomainModel.Models.Province?> GetByIdAsync(int id,bool tracking=true)=>(tracking?c.Provinces:c.Provinces.AsNoTracking()).FirstOrDefaultAsync(x=>x.ProvinceID==id); public Task AddAsync(DomainModel.Models.Province e)=>c.Provinces.AddAsync(e).AsTask(); public void Remove(DomainModel.Models.Province e)=>c.Provinces.Remove(e); public async Task<bool> HasDependenciesAsync(int id)=> await c.Cities.AnyAsync(x=>x.ProvinceID==id) || await c.Advertisements.AnyAsync(x=>x.ProvinceID==id); public Task<int> SaveChangesAsync()=>c.SaveChangesAsync(); }
